// D758 (#1864) — the documents the platform generates in code, for the
// Templates catalog's "Generated by the platform" group.
//
// Ten documents have no `legal_templates` row of their own: the seven notice
// types, the Subscription Booklet, the Structure of the Fund page and the
// certificate of completion. This module lists them from the code that builds
// them (never retyped), says which library rows each one reads and whether
// each row has a body, and builds each one's page 1 as a specimen for its
// thumbnail.
//
// It reads only the library (`getTemplate`), never an account or a record: no
// LP, call, notice, booklet, application or bank account. It writes nothing.
//
// NOTE: authored to load under `node --experimental-strip-types` (the worker
// test gate) — no `enum`s, no TS parameter properties.

import type { Env } from '../types';
import { AXAL_ENTITIES, SUBSCRIPTION_BOOKLET_PARTS, type AxalEntityKey } from './legalDocFormat';
import { NOTICE_TYPES, canonicalJson, noticeBodyRefusal, noticePaperInput, noticeSpecimen, sha256Hex, type NoticeType } from './fundNotices';
import { BOOKLET_TITLE, READ_PARTS, bookletMissingSentence, bookletSpecimenInput, resolveParts } from './subscriptionBooklet';
import { STRUCTURE_HEADING } from './fundStructurePaper';
import { fundStructureModel } from './fundStructure';
import { CERTIFICATE_HEADING, type PaperInput } from './legalPaper';
import { getTemplate } from './legalTemplateStore';
import { COUNSEL_DRAFT_SLUGS } from './templateFormat';

export type GeneratedKind = 'notice' | 'booklet' | 'page';
export type GeneratedOnly = 'structure' | 'certificate' | null;

export interface GeneratedDocument {
  key: string;
  /** The paper's own title. */
  title: string;
  kind: GeneratedKind;
  party: AxalEntityKey | 'per_entity' | 'none';
  party_line: string;
  /** The library rows it reads, in order; a booklet row names its part. */
  prose: { slug: string; part?: number }[];
}

const forTheFund = `${AXAL_ENTITIES.gp.name} (for the Fund)`;

/** The party line each notice type prints on its card (decision 1). */
const NOTICE_PARTY: Record<NoticeType, { party: AxalEntityKey | 'per_entity'; line: string }> = {
  capital_call_notice: { party: 'fund', line: forTheFund },
  distribution_notice: { party: 'fund', line: forTheFund },
  default_notice: { party: 'fund', line: forTheFund },
  management_fee_statement: { party: 'fund', line: `${forTheFund}, to each limited partner` },
  management_fee_invoice: { party: 'gp', line: `${AXAL_ENTITIES.gp.name}, to the Fund` },
  platform_licence_fee_invoice: { party: 'holdings', line: `${AXAL_ENTITIES.holdings.name}, to its licensee` },
  payment_instructions_letter: { party: 'per_entity', line: 'Issued per entity' },
  // D802 (#2238): HQ's annual fee invoice to a territory licensee.
  territory_licence_fee_invoice: { party: 'holdings', line: `${AXAL_ENTITIES.holdings.name}, to a territory licensee` },
};

/** Decision 1's ten, and D802's territory licence fee invoice, in order, built from the code. */
export const GENERATED_DOCUMENTS: readonly GeneratedDocument[] = Object.freeze([
  ...NOTICE_TYPES.map((t): GeneratedDocument => ({
    key: t.type, title: t.title, kind: 'notice', party: NOTICE_PARTY[t.type].party, party_line: NOTICE_PARTY[t.type].line,
    prose: t.prose ? [{ slug: t.type }] : [],
  })),
  {
    key: 'subscription_booklet', title: BOOKLET_TITLE, kind: 'booklet', party: 'fund', party_line: forTheFund,
    prose: SUBSCRIPTION_BOOKLET_PARTS.filter((p) => p.slug && READ_PARTS.has(p.part)).map((p) => ({ slug: p.slug as string, part: p.part })),
  },
  {
    key: 'structure_of_the_fund', title: STRUCTURE_HEADING, kind: 'page', party: 'none',
    party_line: 'carried by the PPM, the Subscription Booklet and the Compliance Manual', prose: [],
  },
  {
    key: 'certificate_of_completion', title: CERTIFICATE_HEADING, kind: 'page', party: 'none',
    party_line: 'appended to every signed copy', prose: [],
  },
] as GeneratedDocument[]);

export const isGeneratedKey = (key: unknown): key is string => GENERATED_DOCUMENTS.some((d) => d.key === key);
const entryOf = (key: string) => GENERATED_DOCUMENTS.find((d) => d.key === key)!;

/** The certificate's specimen, in L4's brackets (decision 8). */
function certificateSpecimen(): PaperInput {
  return {
    title: '[Document title]',
    body: '',
    slug: null,
    version: null,
    bodySha256: '[64 hex characters]',
    envelopeUuid: '[envelope id]',
    merge: 'brackets',
    state: { kind: 'specimen' },
    certificate: true,
    recipients: [
      { name: '[Signer]', status: 'signed' },
      { name: '[Counterparty signer]', status: 'signed' },
    ],
  };
}

/**
 * A generated document's page 1 as a specimen (decisions 5 and 8): its paper
 * input, the one section it draws alone (or null), and `version`, the first 16
 * hex of its hash, which names its thumbnail. A failure throws.
 */
export async function generatedSpecimen(env: Env, key: string): Promise<{ input: PaperInput; only: GeneratedOnly; version: string }> {
  const entry = entryOf(key);
  let input: PaperInput;
  let only: GeneratedOnly = null;
  if (entry.kind === 'notice') {
    input = { ...noticePaperInput(await noticeSpecimen(env, key)), state: { kind: 'specimen' } };
  } else if (key === 'subscription_booklet') {
    input = { ...(await bookletSpecimenInput(env)), structure: await fundStructureModel(env, { audience: 'preview' }) };
  } else if (key === 'structure_of_the_fund') {
    // `ppm` only passes the map's gate; `only` keeps its cover and preamble off the page.
    input = {
      title: STRUCTURE_HEADING, body: '', slug: 'ppm', bodySha256: 'f'.repeat(64), merge: 'brackets',
      state: { kind: 'specimen' }, structure: await fundStructureModel(env, { audience: 'preview' }),
    };
    only = 'structure';
  } else {
    input = certificateSpecimen();
    only = 'certificate';
  }
  const version = (await sha256Hex(canonicalJson({ input, only }))).slice(0, 16);
  return { input, only, version };
}

export interface GeneratedProseRow {
  slug: string;
  part: number | null;
  title: string | null;
  has_body: boolean;
  counsel_draft: boolean;
  missing: boolean;
}

export interface GeneratedListItem {
  key: string;
  title: string;
  kind: GeneratedKind;
  party: GeneratedDocument['party'];
  party_line: string;
  prose: GeneratedProseRow[];
  refusal: { code: string; message: string; parts?: number[] } | null;
  thumbnail_version: string;
}

/** Decision 6: each entry with its library rows' states, its refusal and its thumbnail's version. */
export async function generatedList(env: Env): Promise<GeneratedListItem[]> {
  const rows = new Map<string, GeneratedProseRow>();
  for (const entry of GENERATED_DOCUMENTS) {
    for (const p of entry.prose) {
      if (rows.has(p.slug)) continue;
      const tpl = await getTemplate(env, p.slug);
      rows.set(p.slug, {
        slug: p.slug, part: null, title: tpl?.title ?? null,
        has_body: !!tpl && !tpl.is_stub && String(tpl.body_md || '').trim() !== '',
        counsel_draft: COUNSEL_DRAFT_SLUGS.has(p.slug),
        missing: !tpl,
      });
    }
  }
  const out: GeneratedListItem[] = [];
  for (const entry of GENERATED_DOCUMENTS) {
    let refusal: GeneratedListItem['refusal'] = null;
    if (entry.kind === 'notice' && entry.prose.length) {
      refusal = await noticeBodyRefusal(env, entry.prose[0].slug);
    } else if (entry.kind === 'booklet') {
      const missing = (await resolveParts(env)).filter((p) => p.missing).map((p) => p.part);
      if (missing.length) refusal = { code: 'booklet_part_missing', message: bookletMissingSentence(missing), parts: missing };
    }
    out.push({
      key: entry.key, title: entry.title, kind: entry.kind, party: entry.party, party_line: entry.party_line,
      prose: entry.prose.map((p) => ({ ...rows.get(p.slug)!, part: p.part ?? null })),
      refusal,
      thumbnail_version: (await generatedSpecimen(env, entry.key)).version,
    });
  }
  return out;
}
